import {PROGRAMS,SOURCES,SUBJECTS,DIRECTIONS,VERIFIED_AT} from './data.mjs';
import {defaultFilters,matches,status,scope,graduationConflict,pendingTasks} from './engine.mjs';
const $=s=>document.querySelector(s);
const html=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icons={compass:'<circle cx="12" cy="12" r="9"/><path d="m16 8-2 6-6 2 2-6z"/>',bookmark:'<path d="M6 4h12v17l-6-4-6 4z"/>',columns:'<rect x="3" y="4" width="18" height="16" rx="2"/><path d="M9 4v16M15 4v16"/>',checklist:'<path d="m3 6 2 2 3-3m-5 8 2 2 3-3m-5 8 2 2 3-3M12 6h9M12 13h9M12 20h9"/>',book:'<path d="M12 6C8 3 5 4 2 4v15c3 0 6-1 10 2 4-3 7-2 10-2V4c-3 0-6-1-10 2v15"/>',lock:'<rect x="5" y="10" width="14" height="11" rx="2"/><path d="M8 10V7a4 4 0 0 1 8 0v3M12 14v3"/>',help:'<circle cx="12" cy="12" r="9"/><path d="M9.5 9a2.5 2.5 0 1 1 4.4 1.6C12 12 12 12 12 14m0 3h.01"/>',search:'<circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 5 5"/>',arrow:'<path d="M4 12h16m-6-6 6 6-6 6"/>',external:'<path d="M14 3h7v7m-1-6L10 14M10 4H4v16h16v-6"/>',pin:'<path d="M19 9c0 5-7 12-7 12S5 14 5 9a7 7 0 0 1 14 0z"/><circle cx="12" cy="9" r="2"/>',check:'<path d="m5 12 4 4L20 5"/>',filter:'<path d="M3 6h18M6 12h12M9 18h6"/>',download:'<path d="M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5"/>',upload:'<path d="M12 16V4m-5 5 5-5 5 5M4 16v5h16v-5"/>',close:'<path d="m6 6 12 12M18 6 6 18"/>'};
const icon=(k)=>`<svg viewBox="0 0 24 24" aria-hidden="true">${icons[k]||icons.book}</svg>`;
document.querySelectorAll('[data-icon]').forEach(e=>e.innerHTML=icon(e.dataset.icon));
const KEY='shinro-plan-v1';
let saved={};try{saved=JSON.parse(localStorage.getItem(KEY)||'{}')}catch{}
const validIds=new Set(PROGRAMS.map(p=>p.id));
let records=saved.records&&typeof saved.records==='object'&&!Array.isArray(saved.records)?saved.records:{};
let picks=Array.isArray(saved.picks)?[...new Set(saved.picks.filter(x=>validIds.has(x)))].slice(0,4):[];
let filters={...defaultFilters(),...(saved.filters||{})};
for(const k of ['regions','directions','subjects','avoid'])if(!Array.isArray(filters[k]))filters[k]=[];
for(const k of ['q','format','english','intake','contact','grad'])if(typeof filters[k]!=='string')filters[k]='';
let view='explore',sort='default',shortStatus='',mobileFilters=false,detailId=null,detailTab='overview',diffOnly=false,sourceQuery='';
const labels={explore:'探索项目',shortlist:'候选清单',compare:'横向比较',verify:'核实清单',sources:'官方资料库'};
const record=id=>records[id]||{};
const isSaved=id=>!!record(id).saved;
let storageWarning=false;
function persist(){try{localStorage.setItem(KEY,JSON.stringify({schema:1,records,picks,filters,updatedAt:new Date().toISOString()}));}catch{if(!storageWarning){storageWarning=true;toast('浏览器未允许保存，请使用备份导出保留个人记录。');}}}
let toastTimer;function toast(message){$('#toast').textContent=message;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),3200)}
function ref(id,label='官方依据'){if(Array.isArray(id))return id.map((item,i)=>ref(item,label+(id.length>1?' '+(i+1):''))).join(' ');const s=SOURCES[id];return s?`<a class="ref-link" href="${html(s.url)}" target="_blank" rel="noopener noreferrer" title="${html(s.title+' · '+s.loc)}">${html(label)} ${icon('external')}</a>`:''}
const intake=p=>p.intake.replace('-04','年4月').replace('-10','年10月');
function toggleSaved(id){records[id]={...record(id),saved:!isSaved(id)};persist();updateChrome();renderMain();if(detailId===id)renderDetail();toast(isSaved(id)?'已加入候选清单':'已从候选清单移除')}
function togglePick(id,force){const next=force??!picks.includes(id);if(next&&!picks.includes(id)){if(picks.length>=4){toast('最多比较4条路径，请先移除一条。');renderMain();return}picks.push(id)}else if(!next){picks=picks.filter(x=>x!==id)}persist();updateChrome();if(view==='compare')renderMain();else document.querySelectorAll('input[data-pick]').forEach(e=>e.checked=picks.includes(e.dataset.pick));if(detailId)renderDetail()}
function updateChrome(){const savedCount=PROGRAMS.filter(p=>isSaved(p.id)).length;$('#nav-total').textContent=PROGRAMS.length;$('#nav-saved').textContent=savedCount;$('#nav-compare').textContent=picks.length;$('#breadcrumb').textContent=labels[view];document.querySelectorAll('[data-nav]').forEach(a=>{a.classList.toggle('active',a.dataset.nav===view);if(a.dataset.nav===view)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current')});
const tray=$('#compare-tray');tray.hidden=!picks.length||view==='compare';if(!tray.hidden)tray.innerHTML=`<div class="tray-meta">已选择 ${picks.length} / 4 条路径<small>跨筛选保留，至少选择2条</small></div><div class="tray-picks">${picks.map(id=>{const p=PROGRAMS.find(x=>x.id===id);return `<span class="tray-pick">${html(p.code)} · ${p.intake.endsWith('10')?'秋':'春'}<button data-action="remove-pick" data-id="${id}" aria-label="移除${html(p.school+intake(p))}">×</button></span>`}).join('')}</div><button class="link-button" data-action="clear-picks">清空</button><button class="button primary" data-action="go-compare" ${picks.length<2?'disabled':''}>横向比较 ${icon('arrow')}</button>`;
}
function badge(p){const s=status(p);return `<span class="badge ${s.tone}">${s.text}</span>`}
function card(p){const rec=record(p.id),conflict=graduationConflict(p,filters.grad);const subjectLabels=scope(p).slice(0,5).map(s=>SUBJECTS[s]).join('、');return `<article class="card" data-card="${p.id}"><div class="card-top"><span class="monogram" aria-hidden="true">${p.code==='NAIST'?'奈':p.code==='JAIST'?'北':html(p.school.charAt(0))}</span><div class="card-school"><h3>${html(p.school)}</h3><div class="en">${html(p.en)}</div></div><button class="save-button ${rec.saved?'saved':''}" data-action="save" data-id="${p.id}" aria-label="${rec.saved?'取消收藏':'收藏'}${html(p.school)}" aria-pressed="${!!rec.saved}" title="${rec.saved?'取消收藏':'加入候选'}">${icon('bookmark')}</button></div><div class="location">${icon('pin')}${html(p.city)}<span> · ${intake(p)}入学</span></div><div class="program-name">${html(p.program)}</div><div class="group-name">${html(p.group)}</div><div class="route-name">${html(p.route)}</div><div class="badgerow"><span class="badge green">${html(p.format==='written'?'笔试路径':p.format==='oral'?'口试路径':'在线面谈')}</span>${badge(p)}${!p.examKnown?'<span class="badge amber">科目细目待核实</span>':p.examPartial?'<span class="badge line">专业口试细目待核实</span>':''}${conflict?'<span class="badge amber">毕业日期冲突</span>':''}</div><div class="card-spec"><span class="label">考查</span><span class="value">${p.examKnown?html(subjectLabels)+(scope(p).length>5?' 等':''):'数学 / 专业题范围待核实'}${p.choices.length?'<span class="subtle"> · 含选答</span>':''}</span></div><div class="card-spec"><span class="label">语言</span><span class="value">${html([...new Set(p.english.map(e=>e.startsWith('TOEIC')?'TOEIC':e))].join(' / '))}${p.code==='JAIST'?' 或日语证明':''}${p.code==='KYUSHU'?' · TOEIC仅日本受验':''}</span></div><div class="direction-row">${p.directions.slice(0,3).map(d=>`<span>${html(d)}</span>`).join('')}${p.directions.length>3?`<span>+${p.directions.length-3}</span>`:''}</div>${view==='shortlist'?`<div class="record-strip">${html(rec.priority||'待评估')}${rec.note?`<span class="note-preview">${html(rec.note)}</span>`:''}</div>`:''}<div class="card-notice">${html(p.notice||'确认教授接收、个人资格与语学材料后再决定出愿。')}</div><div class="card-bottom"><button data-action="detail" data-id="${p.id}">查看路径与依据 ↗</button><label class="compare-check"><input type="checkbox" data-pick="${p.id}" ${picks.includes(p.id)?'checked':''}>加入比较</label></div></article>`}
function chips(key,options,avoid=false){return `<div class="chipset">${options.map(([val,name])=>`<label class="chip ${avoid?'avoid':''} ${filters[key].includes(val)?'selected':''}"><input type="checkbox" data-filter-list="${key}" value="${html(val)}" ${filters[key].includes(val)?'checked':''}>${html(name)}</label>`).join('')}</div>`}
function selectFilter(key,label,options){return `<div class="filter-group"><label for="f-${key}">${label}</label><select id="f-${key}" data-filter="${key}"><option value="">不限</option>${options.map(([v,l])=>`<option value="${v}" ${filters[key]===v?'selected':''}>${l}</option>`).join('')}</select></div>`}
function filterPanel(){return `<aside class="filterbox ${mobileFilters?'mobile-open':''}" aria-label="项目筛选条件"><div class="filtertop"><h2>${icon('filter')} 筛选条件</h2><button class="link-button" data-action="reset">重置</button></div><div class="filter-group"><label>地区 <span class="filtercount">任一匹配</span></label>${chips('regions',['关东','关西','中部','九州'].map(x=>[x,x]))}</div><div class="filter-group"><label>研究方向 <span class="filtercount">任一匹配</span></label>${chips('directions',DIRECTIONS.map(x=>[x,x]))}<p class="hint">按官方研究主题归纳，需进一步确认研究室招生。</p></div>${selectFilter('format','考试形式',[['written','含书面笔试'],['oral','赴日对面口试'],['online','在线面试 / 面谈']])}${selectFilter('english','英语成绩类型',[['TOEFL','TOEFL'],['TOEIC-CN','TOEIC L&R · 中国受验'],['TOEIC-JP','TOEIC L&R · 日本受验'],['IELTS','IELTS'],['Duolingo','Duolingo']])}${selectFilter('intake','已核实入学批次',[['2027-04','2027年4月'],['2027-10','2027年10月']])}<p class="hint">仅筛已列明的成绩类型；具体版本、分数、有效期仍须读要项。</p><label class="checkline"><input type="checkbox" data-filter="future" ${filters.future?'checked':''}><span>仅看尚未过首个手续节点</span></label><details class="advanced" ${filters.subjects.length||filters.avoid.length||filters.grad||filters.contact||filters.overseas?'open':''}><summary>科目与个人条件</summary><div class="filter-group"><label>考查范围包含 <span class="filtercount">全部包含</span></label>${chips('subjects',Object.entries(SUBJECTS))}<p class="hint">含必答、可能出题范围或选答科目，不代表每科均必考。</p></div><div class="filter-group"><label>不想准备的科目</label>${chips('avoid',Object.entries(SUBJECTS),true)}<p class="hint">遇必答/不可回避范围则排除；选答须仍有足够组合。未知/部分未知范围默认保留。</p><label class="checkline"><input type="checkbox" data-filter="unknown" ${filters.unknown?'checked':''}><span>排除科目时，保留范围待核实项目</span></label></div>${selectFilter('contact','导师联系要求',[['required','需联系 / 内诺或接收手续'],['recommended','官方建议联系'],['unknown','要求待核实']])}<label class="checkline"><input type="checkbox" data-filter="overseas" ${filters.overseas?'checked':''}><span>仅保留境外申请路径已核实项</span></label><div class="filter-group"><label for="f-grad">预计取得本科学位日期</label><input id="f-grad" type="date" data-filter="grad" value="${html(filters.grad)}"><p class="hint">仅检查普通学历路径时间，不自动判断其他资格或特殊资格审查。</p><label class="checkline"><input type="checkbox" data-filter="hideGrad" ${filters.hideGrad?'checked':''}><span>隐藏学历截止早于毕业日的路径</span></label></div></details><p class="updated-note">最后核验 ${VERIFIED_AT}<br>2028年规则待当期公布，不沿用推断。</p></aside>`}
function filtered(){let list=PROGRAMS.filter(p=>matches(p,filters));if(sort==='school')list.sort((a,b)=>a.school.localeCompare(b.school,'zh'));if(sort==='deadline')list.sort((a,b)=>(a.preDeadline||a.deadline).localeCompare(b.preDeadline||b.deadline));if(sort==='pending')list.sort((a,b)=>pendingTasks(a).length-pendingTasks(b).length);return list}
function activeTags(){const a=[];if(filters.q)a.push('搜索：'+filters.q);a.push(...filters.regions,...filters.directions,...filters.subjects.map(s=>'含 '+SUBJECTS[s]),...filters.avoid.map(s=>'回避 '+SUBJECTS[s]));if(filters.format)a.push({written:'含笔试',oral:'对面口试',online:'在线面谈'}[filters.format]);if(filters.english)a.push(filters.english);if(filters.intake)a.push(filters.intake+' 入学');if(filters.contact)a.push('导师联系：'+{required:'必需',recommended:'建议',unknown:'待核实'}[filters.contact]);if(filters.future)a.push('首个手续节点尚未截止');if(filters.overseas)a.push('境外申请已核实');if(filters.grad)a.push('毕业：'+filters.grad);if(filters.hideGrad&&filters.grad)a.push('隐藏学历时间冲突');return a}
function empty(title,text,buttons='<button class="button primary" data-action="reset">清除筛选条件</button>'){return `<div class="empty"><span class="empty-icon">${icon('compass')}</span><h3>${title}</h3><p>${text}</p>${buttons}</div>`}
function resultBody(){const list=filtered();return `<div class="results-toolbar"><h2><strong>${list.length}</strong> 条路径符合当前条件 <span class="filtercount">/ 共 ${PROGRAMS.length} 条</span></h2><label class="subtle">排序 <select id="sort" aria-label="排序方式"><option value="default">默认顺序</option><option value="school" ${sort==='school'?'selected':''}>学校名称</option><option value="deadline" ${sort==='deadline'?'selected':''}>首个手续节点</option><option value="pending" ${sort==='pending'?'selected':''}>待核实项较少</option></select></label></div>${activeTags().length?`<div class="filter-tags">${activeTags().map(t=>`<span class="filter-tag">${html(t)}</span>`).join('')}</div>`:''}<div class="cards">${list.length?list.map(card).join(''):empty('暂时没有同时符合的路径','可尝试放宽考试科目、研究方向或时间条件。未知科目不会作为“确定包含”命中；只看未截止节点时，已经结束的批次会隐藏。')}</div><p class="hint" style="margin-top:18px">科目与日程仅对应卡片标注的选拔路径。批次状态按今日计算；“尚有准备窗口”不代表个人已具备申请资格。</p>`}
function explore(){return `<section class="hero"><div><span class="kicker">JAPAN · COMPUTER SCIENCE · MASTER'S</span><h1>找到适合你的<em>下一站。</em></h1><p>从考试科目到研究方向，把“想去日本”变成一份有依据的候选清单。<br>为从中国准备赴日参加修士考试而整理。</p></div><div class="hero-graphic" aria-hidden="true"><span class="kicker">ADMISSION REFERENCE</span><div class="year">2027<span>年度</span></div><p>已公布选拔的规则样本<br>2028年度要项待更新</p><div class="orbit"></div></div></section><div class="stats"><div class="stat"><strong>08</strong><span>所大学</span></div><span class="stats-sep"></span><div class="stat"><strong>${PROGRAMS.length}</strong><span>条选拔路径</span></div><span class="stats-sep"></span><div class="trust-tag">${icon('check')} 附官方来源与定位</div></div><div class="planning-note">${icon('help')}<div><b>先确认入学时间。</b> 若2027年夏季本科毕业，你的毕业日期通常晚于2027年4月入学的学历截止日。可查看2027年秋季路径，或将春季规则作下一年度备考参考。</div></div><div class="searchline"><div class="searchbox">${icon('search')}<input id="search" type="search" placeholder="搜索大学、研究科、专攻或研究方向…" aria-label="搜索项目" value="${html(filters.q)}" autocomplete="off"></div><button class="button mobile-filter-toggle" data-action="mobile-filters">${icon('filter')} 筛选</button></div><div class="workgrid">${filterPanel()}<section id="results" aria-label="筛选结果" aria-live="polite">${resultBody()}</section></div>`}
function shortlist(){let list=PROGRAMS.filter(p=>isSaved(p.id)&&(!shortStatus||(record(p.id).priority||'待评估')===shortStatus));return `<div class="page-heading"><div><span class="kicker">YOUR SHORTLIST</span><h1>留下值得继续了解的。</h1><p>收藏只代表感兴趣。逐一确认条件，再缩小选择。</p></div><div class="page-actions"><button class="button" data-action="export-csv">${icon('download')}导出候选CSV</button><button class="button" data-action="backup">备份记录</button><button class="button" data-action="restore">恢复记录</button></div></div><div class="saved-info">收藏、备注与跟进保存在当前浏览器，换设备前可先备份。点开项目的“个人记录”，设置优先级并记录教授、研究主题或疑问。</div><div class="shortlist-tools"><span class="subtle">${list.length} 条收藏路径</span><label class="subtle">优先级 <select id="short-status" aria-label="收藏优先级筛选"><option value="">全部</option>${['待评估','优先考虑','继续观察','暂缓'].map(s=>`<option ${shortStatus===s?'selected':''}>${s}</option>`).join('')}</select></label></div><div class="cards shortlist-cards">${list.length?list.map(card).join(''):empty('候选清单还空着','到探索项目中，点击书签收藏感兴趣的路径。','<a class="button primary" href="#explore">去探索项目 →</a>')}</div>`}
const compareRows=[
 ['program','研究科 / 项目',p=>p.group+' / '+p.program,'direction'],['route','具体选拔',p=>p.route,'schedule'],['intake','入学时间',p=>intake(p),'eligibility'],['status','批次状态',p=>status(p).text,'schedule'],['format','考试方式',p=>p.formatText,'exam'],['exam','考试科目与选答',p=>p.examText,'exam'],['english','英语要求',p=>p.englishText,'english'],['contact','导师前置手续',p=>p.contactText,'contact'],['japanese','日语 / 答题语言',p=>p.japanese,'japanese'],['overseas','中国境内申请',p=>p.overseasText,'eligibility'],['grad','普通学历截止',p=>p.gradDeadline+(graduationConflict(p,filters.grad)?' · 你的毕业日更晚，存在冲突':''),'eligibility'],['application','正式 / 前置日程',p=>p.application,'schedule'],['test','考试日期',p=>p.testDate,'schedule'],['directions','研究方向',p=>p.directions.join('、'),'direction'],['unknown','待核实事项',p=>pendingTasks(p).join('；'),null]
];
function compare(){const list=picks.map(id=>PROGRAMS.find(p=>p.id===id));return `<div class="page-heading"><div><span class="kicker">SIDE BY SIDE</span><h1>把差异放在同一张桌上。</h1><p>比较具体选拔路径，最多4条；同校不同入学期也能一起比较。</p></div><div class="page-actions"><button class="button" data-action="export-csv">${icon('download')}导出比较CSV</button><a class="button" href="#explore">继续添加</a></div></div>${list.length<2?empty('至少选择两条路径','在探索项目或候选清单勾选“加入比较”，已有选择会跨筛选保留。','<a class="button primary" href="#explore">选择比较项目 →</a>'): `<div class="compare-options"><label class="checkline"><input type="checkbox" id="diff-only" ${diffOnly?'checked':''}><span>仅看存在差异的项目</span></label><button class="link-button" data-action="clear-picks">清空比较</button></div><div class="compare-wrap"><table class="compare-table"><caption class="skip">修士选拔路径横向比较</caption><thead><tr><th scope="col">比较维度</th>${list.map(p=>`<th scope="col"><button class="icon-button remove-compare" data-action="remove-pick" data-id="${p.id}" aria-label="移除${html(p.school)}">${icon('close')}</button><h3>${html(p.school)}</h3><div class="compare-route">${html(p.route)}</div><button class="link-button" data-action="detail" data-id="${p.id}">查看完整资料</button></th>`).join('')}</tr></thead><tbody>${compareRows.map(([key,name,fn,source])=>{const values=list.map(fn),different=new Set(values).size>1;if(diffOnly&&!different)return '';return `<tr class="${different?'difference':''}"><th scope="row">${name}</th>${list.map((p,i)=>`<td>${html(values[i])}${source?ref(p.refs[source]):'<span class="choice-note">资料缺口与个人核对事项</span>'}</td>`).join('')}</tr>`}).join('')}</tbody></table></div><p class="hint" style="margin-top:15px">浅绿色行表示该维度存在差异。“待核实”不会被视为没有要求；个人毕业日期可在探索页的高级筛选中设置。</p>`}`}
function verify(){const list=PROGRAMS.filter(p=>isSaved(p.id));const total=list.reduce((n,p)=>n+pendingTasks(p).length,0),done=list.reduce((n,p)=>n+pendingTasks(p).filter((_,i)=>(record(p.id).done||[]).includes(i)).length,0);return `<div class="page-heading"><div><span class="kicker">CHECK BEFORE YOU APPLY</span><h1>把不确定，逐项确认。</h1><p>候选项目的待核实事项，集中跟进。</p></div><span class="badge green">个人跟进 ${done} / ${total}</span></div><p class="verify-intro">勾选仅表示你已跟进，不修改官方资料或其核验状态。建议在个人笔记中记录答复、链接与核对日期。</p>${list.length?list.map(p=>{const tasks=pendingTasks(p),checked=record(p.id).done||[],n=tasks.filter((_,i)=>checked.includes(i)).length;return `<section class="verify-group"><header><div><h2>${html(p.school)} · ${html(p.route)}</h2><span class="subtle">${intake(p)}入学 · ${n}/${tasks.length} 已跟进</span></div><button class="button small" data-action="note" data-id="${p.id}">个人记录</button></header><div class="progress"><i style="width:${n/tasks.length*100}%"></i></div>${tasks.map((task,i)=>`<label class="checkline ${checked.includes(i)?'done':''}"><input type="checkbox" data-task="${i}" data-id="${p.id}" ${checked.includes(i)?'checked':''}><span>${html(task)}</span></label>`).join('')}${ref(p.refs.eligibility,'打开官方招生资料')}</section>`}).join(''):empty('先收藏，再跟进','收藏项目后，这里会自动汇总它的资料缺口和需要你确认的个人条件。','<a class="button primary" href="#explore">去收藏项目 →</a>')}`}
function sourceList(){const entries=Object.entries(SOURCES).filter(([id,s])=>[s.title,s.url,s.loc,s.year,...PROGRAMS.filter(p=>p.sourceIds.includes(id)).map(p=>p.school)].join(' ').toLowerCase().includes(sourceQuery.trim().toLowerCase()));return `<div class="sources-summary">${entries.length} 份资料 · 仅采用大学官方来源 · 最近核验 ${VERIFIED_AT}</div>${entries.map(([id,s],i)=>`<article class="source-card"><span class="source-index">${String(i+1).padStart(2,'0')}</span><div><h2>${html(s.title)}</h2><p>${html(s.year)} · ${html(s.loc)}</p><p class="domain">${html(new URL(s.url).hostname)} · 核验 ${VERIFIED_AT}</p></div><a href="${html(s.url)}" target="_blank" rel="noopener noreferrer" aria-label="打开${html(s.title)}">${icon('external')}</a></article>`).join('')||empty('没有匹配的官方资料','换个大学名称或关键词试试。','')}`}
function sources(){return `<div class="page-heading"><div><span class="kicker">PRIMARY SOURCES ONLY</span><h1>每一项条件，都能追溯。</h1><p>直接阅读学校原文。PDF页码以“PDF”或“印刷”区分；新批次请另查。</p></div></div><div class="saved-info">资料为2026-10-26人工核验的静态快照，未自动刷新。学校可能修改要项；正式出愿前请重新检查原文与更正公告。研究方向为官方主题的中文归纳，非导师接收承诺。</div><div class="searchline"><div class="searchbox">${icon('search')}<input type="search" id="source-search" value="${html(sourceQuery)}" aria-label="搜索官方资料" placeholder="搜索大学、资料名称或内容…"></div></div><div id="source-results">${sourceList()}</div>`}
function renderMain(){const y=window.scrollY;$('#main').innerHTML={explore,shortlist,compare,verify,sources}[view]();window.scrollTo(0,y)}
function route(){if(location.hash==='#main')return;view=labels[location.hash.slice(1)]?location.hash.slice(1):'explore';updateChrome();renderMain();window.scrollTo(0,0)}
window.addEventListener('hashchange',route);
function detailBlock(title,text,source){return `<section class="detail-block"><h3>${title}</h3><p>${html(text)}</p>${source?ref(source):''}</section>`}
function renderDetail(){const p=PROGRAMS.find(p=>p.id===detailId);if(!p)return;const rec=record(p.id),tasks=pendingTasks(p);let content='';if(detailTab==='overview'){content=`${graduationConflict(p,filters.grad)?`<div class="danger-note">你填的毕业日 ${html(filters.grad)} 晚于此路径普通学历截止 ${p.gradDeadline}，通常不满足该学历时间要求。特殊资格另向学校确认。</div>`:''}<div class="detail-facts"><div class="detail-fact"><small>入学 / 学历截止</small>${intake(p)} / ${p.gradDeadline}</div><div class="detail-fact"><small>考试方式 / 批次</small>${html(p.formatText)} · ${status(p).text}</div></div>${detailBlock('考试科目与选答规则',p.examText,p.refs.exam)}${!p.examKnown?'<div class="danger-note">科目细目待核实：不可把“无统一笔试列表”理解成“免数学 / 免专业考查”。</div>':''}${detailBlock('外部英语成绩',p.englishText,p.refs.english)}${detailBlock('日语与考试语言',p.japanese,p.refs.japanese)}${detailBlock('导师联系与前置手续',p.contactText,p.refs.contact)}${detailBlock('从中国申请的条件',p.overseasText+' 普通学历截止：'+p.gradDeadline+'。仅核对路径，不代替个人资格审查。',p.refs.eligibility)}${detailBlock('本批次日程（日本时间）',p.application+'；考试：'+p.testDate,p.refs.schedule)}${detailBlock('研究方向',p.directions.join('、')+'。标签按官方研究主题归纳，导师是否接收须另核实。',p.refs.direction)}${p.notice?detailBlock('路径提醒',p.notice):''}`;}else if(detailTab==='sources'){content=`<p class="subtle" style="margin:0 0 18px">资料年度与位置如下。待核实项不会被显示为已确认规则。</p>${p.sourceIds.map(id=>{const s=SOURCES[id];return `<div class="source-detail"><a href="${html(s.url)}" target="_blank" rel="noopener noreferrer">${html(s.title)} ${icon('external')}</a><p>${html(s.loc)}</p><small>${html(s.year)} · 核验 ${p.verified}</small><p class="source-domain">${html(s.url)}</p></div>`}).join('')}<h3 style="font-size:12px;margin-top:24px">仍需确认</h3>${tasks.map(t=>`<p class="subtle">• ${html(t)}</p>`).join('')}`;}else{content=`<label class="note-label" for="priority">考虑优先级</label><select class="record-select" id="priority" data-record="priority">${['待评估','优先考虑','继续观察','暂缓'].map(s=>`<option ${(rec.priority||'待评估')===s?'selected':''}>${s}</option>`).join('')}</select><p class="hint">优先级不代表录取难度或录取概率。</p><div style="margin-top:22px"><label class="note-label" for="personal-note">个人笔记</label><textarea class="note-input" id="personal-note" maxlength="12000" placeholder="记录想联系的教授、研究主题、学校答复及核对日期…">${html(rec.note||'')}</textarea><div class="note-status">输入后自动保存在当前浏览器。${isSaved(p.id)?'已在候选清单中。':'此项目尚未收藏。'}</div></div><h3 style="font-size:12px;margin-top:24px">待核实事项 · 个人跟进</h3>${tasks.map((task,i)=>`<label class="checkline ${(rec.done||[]).includes(i)?'done':''}"><input type="checkbox" data-task="${i}" data-id="${p.id}" ${(rec.done||[]).includes(i)?'checked':''}><span>${html(task)}</span></label>`).join('')}`}
$('#detail-content').innerHTML=`<div class="dialog-head"><div><span class="kicker">${p.code} · PATHWAY</span><h2 id="detail-title">${html(p.school)}</h2><div class="subtitle">${html(p.group)} / ${html(p.program)}<br>${html(p.route)}</div></div><button class="icon-button" data-action="close-detail" aria-label="关闭项目详情">${icon('close')}</button></div><div class="detail-tabs" role="tablist" aria-label="项目详情标签">${[['overview','选拔详情'],['sources','来源与缺口'],['notes','个人记录']].map(([key,name])=>`<button role="tab" id="tab-${key}" aria-selected="${key===detailTab}" aria-controls="detail-panel" data-action="detail-tab" data-tab="${key}" class="${key===detailTab?'active':''}">${name}</button>`).join('')}</div><div class="dialog-body" id="detail-panel" role="tabpanel" aria-labelledby="tab-${detailTab}">${content}<div class="detail-actions"><button class="button ${isSaved(p.id)?'soft':'primary'}" data-action="save" data-id="${p.id}">${icon('bookmark')}${isSaved(p.id)?'已收藏 · 点击移除':'加入候选清单'}</button><button class="button" data-action="pick" data-id="${p.id}">${icon('columns')}${picks.includes(p.id)?'移出比较':'加入比较'}</button></div><p class="hint">最后核验 ${VERIFIED_AT} · 静态资料快照，正式出愿前请复核。</p></div>`;
}
function openDetail(id,tab='overview'){detailId=id;detailTab=tab;renderDetail();$('#detail-dialog').showModal();$('#detail-dialog').scrollTop=0}
function exportDownload(name,type,text){const blob=new Blob([text],{type}),a=document.createElement('a'),u=URL.createObjectURL(blob);a.href=u;a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(u),1000)}
function csvExport(){const list=view==='compare'?PROGRAMS.filter(p=>picks.includes(p.id)):view==='shortlist'?PROGRAMS.filter(p=>isSaved(p.id)):filtered();if(!list.length){toast('没有可导出的路径');return}const headers=['大学','研究科','项目','选拔路径','入学','普通学历截止','批次状态','考试形式','考试科目与选答','英语','日语','导师手续','海外申请','正式与前置日程','考试时间','研究方向','待核实','优先级','笔记','核验日期','官方来源'];const safe=x=>{let s=String(x??'');if(/^[=+@\-\t\r]/.test(s))s="'"+s;return '"'+s.replace(/"/g,'""')+'"'};const rows=list.map(p=>[p.school,p.group,p.program,p.route,intake(p),p.gradDeadline,status(p).text,p.formatText,p.examText,p.englishText,p.japanese,p.contactText,p.overseasText,p.application,p.testDate,p.directions.join('；'),pendingTasks(p).join('；'),record(p.id).priority||'待评估',record(p.id).note||'',p.verified,p.sourceIds.map(id=>SOURCES[id].url).join('\n')]);exportDownload('日本修士择校_'+view+'.csv','text/csv;charset=utf-8','\uFEFF'+[headers,...rows].map(row=>row.map(safe).join(',')).join('\r\n'));toast(`已导出 ${list.length} 条路径，含官方来源`)}
function normalizeBackup(raw){if(!raw||raw.schema!==1||!raw.records||typeof raw.records!=='object'||Array.isArray(raw.records))throw new Error('文件不是進路的v1备份');const clean={};for(const p of PROGRAMS){const r=raw.records[p.id];if(!r||typeof r!=='object')continue;clean[p.id]={saved:!!r.saved,note:typeof r.note==='string'?r.note.slice(0,12000):'',priority:['待评估','优先考虑','继续观察','暂缓'].includes(r.priority)?r.priority:'待评估',done:Array.isArray(r.done)?r.done.filter(n=>Number.isInteger(n)&&n>=0&&n<pendingTasks(p).length):[]}}return {records:clean,picks:Array.isArray(raw.picks)?[...new Set(raw.picks.filter(id=>validIds.has(id)))].slice(0,4):[]}}
$('#import-file').addEventListener('change',async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>2e6)throw new Error('备份文件过大');const clean=normalizeBackup(JSON.parse(await file.text()));for(const [id,r]of Object.entries(clean.records)){const old=record(id);records[id]={...old,...r,saved:old.saved||r.saved,note:[old.note,r.note].filter(Boolean).filter((x,i,a)=>a.indexOf(x)===i).join('\n\n').slice(0,12000),done:[...new Set([...(old.done||[]),...r.done])]}}picks=[...new Set([...picks,...clean.picks])].slice(0,4);persist();updateChrome();renderMain();toast('备份已合并恢复，原有收藏和笔记已保留');}catch(err){toast('无法恢复：'+err.message)}e.target.value=''});
document.addEventListener('click',e=>{const el=e.target.closest('[data-action]');if(!el)return;const {action,id}=el.dataset;switch(action){case'save':toggleSaved(id);break;case'pick':togglePick(id);break;case'remove-pick':togglePick(id,false);break;case'clear-picks':picks=[];persist();updateChrome();renderMain();break;case'go-compare':location.hash='compare';break;case'detail':openDetail(id);break;case'note':openDetail(id,'notes');break;case'close-detail':$('#detail-dialog').close();detailId=null;break;case'close-help':$('#help-dialog').close();break;case'detail-tab':detailTab=el.dataset.tab;renderDetail();$('#tab-'+detailTab).focus();break;case'reset':filters=defaultFilters();persist();renderMain();break;case'mobile-filters':mobileFilters=!mobileFilters;$('.filterbox')?.classList.toggle('mobile-open',mobileFilters);break;case'export-csv':csvExport();break;case'backup':exportDownload('shinro-plan-backup.json','application/json',JSON.stringify({schema:1,records,picks,filters,verifiedAt:VERIFIED_AT,updatedAt:new Date().toISOString()},null,2));toast('已导出个人记录备份');break;case'restore':$('#import-file').click();break;}});
document.addEventListener('input',e=>{const el=e.target;if(el.id==='search'){filters.q=el.value;persist();$('#results').innerHTML=resultBody()}if(el.id==='source-search'){sourceQuery=el.value;$('#source-results').innerHTML=sourceList()}if(el.id==='personal-note'&&detailId){records[detailId]={...record(detailId),note:el.value};persist();$('.note-status').textContent='已自动保存在当前浏览器。'}});
document.addEventListener('change',e=>{const el=e.target;if(el.dataset.filterList){const k=el.dataset.filterList,v=el.value;filters[k]=el.checked?[...new Set([...filters[k],v])]:filters[k].filter(x=>x!==v);persist();renderMain()}else if(el.dataset.filter){filters[el.dataset.filter]=el.type==='checkbox'?el.checked:el.value;persist();renderMain()}else if(el.dataset.pick){togglePick(el.dataset.pick,el.checked)}else if(el.dataset.task){const id=el.dataset.id,n=Number(el.dataset.task),done=record(id).done||[];records[id]={...record(id),done:el.checked?[...new Set([...done,n])]:done.filter(x=>x!==n)};persist();el.closest('.checkline').classList.toggle('done',el.checked);if(view==='verify')renderMain()}else if(el.id==='sort'){sort=el.value;$('#results').innerHTML=resultBody()}else if(el.id==='short-status'){shortStatus=el.value;renderMain()}else if(el.id==='diff-only'){diffOnly=el.checked;renderMain()}else if(el.dataset.record&&detailId){records[detailId]={...record(detailId),[el.dataset.record]:el.value};persist();if(view==='shortlist')renderMain()}});
$('#help').addEventListener('click',()=>$('#help-dialog').showModal());
$('#detail-dialog').addEventListener('close',()=>{detailId=null;if(view==='shortlist'||view==='verify')renderMain()});
for(const id of ['detail-dialog','help-dialog'])$('#'+id).addEventListener('click',e=>{if(e.target===e.currentTarget){const r=e.currentTarget.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.currentTarget.close()}});
document.addEventListener('keydown',e=>{if(e.target.matches('[role=tab]')&&['ArrowRight','ArrowLeft','Home','End'].includes(e.key)){e.preventDefault();const tabs=['overview','sources','notes'];let i=tabs.indexOf(detailTab);i=e.key==='Home'?0:e.key==='End'?2:(i+(e.key==='ArrowRight'?1:-1)+3)%3;detailTab=tabs[i];renderDetail();$('#tab-'+detailTab).focus()}});
route();
